  const sob = n >= 6 && n <= 8 ? `<path d="M27 34 L43 ${30 - (n - 6) * 2}" stroke="#fff" stroke-width="4.5" stroke-linecap="round"/><path d="M73 34 L57 ${30 - (n - 6) * 2}" stroke="#fff" stroke-width="4.5" stroke-linecap="round"/>` : '';
