  let seq = 0, ant = null, maxSeq = 0; const quandoS = {};
  sem.forEach((w) => { seq = ant && somaDias(ant, 7) === w ? seq + 1 : 1; ant = w; maxSeq = Math.max(maxSeq, seq); [4, 10, 26, 52].forEach((n) => { if (seq >= n && !quandoS[n]) quandoS[n] = w; }); });
  [[4, 'Um mês sem falhar'], [10, '10 semanas seguidas'], [26, 'Meio ano de constância'], [52, 'Um ano inteiro']].forEach(([n, nome]) => add('s' + n, 'constancia', nome, `${n} semanas seguidas treinando`, quandoS[n] && somaDias(quandoS[n], 6) <= hojeISO() ? somaDias(quandoS[n], 6) : quandoS[n], maxSeq / n, quandoS[n] ? '' : `melhor sequência: ${maxSeq}`));
  // força
  [[10, 'Base de força'], [50, '50 treinos de força'], [100, '100 treinos de força']].forEach(([n, nome]) => { const s = h.sessoes[n - 1]; add('f' + n, 'forca', nome, `${n} treinos de força concluídos`, s && s.iniciado_em, h.sessoes.length / n, s ? '' : `faltam ${n - h.sessoes.length}`); });
  // água
