    for (let j = 1; j <= n; j++) { x.strokeStyle = cores ? cores[j - 1] : corP().p1; x.beginPath(); x.moveTo(P[j - 1][0], P[j - 1][1]); x.lineTo(P[j][0], P[j][1]); x.stroke(); }
    const [px, py] = P[n]; const gl = x.createRadialGradient(px, py, 2, px, py, 50); gl.addColorStop(0, 'rgba(255,255,255,.95)'); gl.addColorStop(1, 'rgba(70,214,255,0)'); x.fillStyle = gl; x.beginPath(); x.arc(px, py, 50, 0, 7); x.fill();
    x.fillStyle = '#fff'; x.beginPath(); x.arc(px, py, 14, 0, 7); x.fill();
    // números ao vivo
    const dk = dist * k, tk = dur * k; let pc = dk > 50 ? tk / (dk / 1000) : null;
    if (ser && ser.t && ser.vel) { const alvo = tk; let jx = ser.t.findIndex((t) => t >= alvo); if (jx < 0) jx = ser.t.length - 1; const vs = ser.vel.slice(Math.max(0, jx - 3), jx + 3).filter((v) => v > 0.8); if (vs.length) pc = 1000 / (vs.reduce((a, b) => a + b, 0) / vs.length); }
    const cols = [['Distância', `${f1(dk / 1000)}`, 'km'], ['Tempo', fmtDurLongo(tk), ''], ['Pace', pc ? fmtPace(pc).replace('/km', '') : '–', '/km']];
    cols.forEach(([l, v, u], j) => { const cx = 90 + j * 320; x.textAlign = 'left'; x.font = "500 34px 'Manrope'"; x.fillStyle = 'rgba(255,255,255,.65)'; x.fillText(l, cx, 1530); x.font = "600 64px 'Unbounded'"; x.fillStyle = '#fff'; x.fillText(v, cx, 1615); if (u) { const w = x.measureText(v).width; x.font = "700 32px 'Manrope'"; x.fillStyle = 'rgba(255,255,255,.7)'; x.fillText(u, cx + w + 8, 1615); } });
    x.font = "700 32px 'Manrope'"; x.fillStyle = '#fff'; x.fillText(S.staff ? '' : (S.me.nome || ''), 90, H - 150);
    x.font = "500 28px 'Manrope'"; x.fillStyle = 'rgba(255,255,255,.6)'; x.fillText('Treino acompanhado pela Nexos Performance e Saúde', 90, H - 100);
