  const forcaHoje = fC ? planoSem.find((p) => p.data === hoje && p.tipo === 'forca') : null;
  const proxCorr = fC ? planoSem.find((p) => p.data > hoje && !semCorrida(p)) : null;
  const h = new Date().getHours();
