    const salvar = () => { try { localStorage.setItem('nx-card', JSON.stringify({ layout: o.layout, fundo: o.fundo === 'foto' ? 'transparente' : o.fundo, cor: o.cor, formato: o.formato, stats: o.stats })); } catch {} };
