      if (k === 'fundo' && b.dataset.v === 'foto') { inp.click(); if (!o.img) return; }
      o[k] = b.dataset.v; if (k === 'fundo' && o.fundo === 'foto') o.cor = 'branco';
      if (k === 'fundo' && o.fundo === 'nexos') o.cor = 'branco';
