  const continuar = () => { if (est) ligarSensor(); ligarGPS(); st.estado = 'correndo'; st.auto = false; autoBase = null; ultMov = Date.now(); marcaMov = Date.now(); ultimo = null; pedirTela(); recuperado && falar('Continuando.'); salvar(); desenha(); };
