const sReg = (min) => cT('regenerativo', `Regenerativo ${min} min`, [_C(min, 'min', 'rec')], 'Trote muito leve (Z1). Recupera sem gerar cansaço.');
const sLon = (km, fimKm, z = 'maratona') => fimKm >= 1 ? cT('longao', `Longão ${String(r05(km)).replace('.', ',')} km com ${String(r05(fimKm)).replace('.', ',')} km em ritmo`, [_C(r05(km - fimKm), 'km', 'leve'), _C(r05(fimKm), 'km', z)], 'Longão leve e o final no ritmo indicado. Treina terminar forte e o ritmo de prova.') : cT('longao', `Longão ${String(r05(km)).replace('.', ',')} km`, [_C(r05(km), 'km', 'leve')], OBS.lon);
