const sSub = (n, m) => cT('tiros', `Subidas ${n} × ${m} m`, [_A(10, 'min'), serie(n, [_C(m, 'm', 'tiros'), _R(1.5, 'min')]), _D(5, 'min')], OBS.sub2);
