    if (fase === 'Específica' || fase === 'Competitiva') return k === 0 ? sVo(Math.round(5 * Math.min(n, 1.6)), 1000) : k === 1 ? sKm(Math.round(3 * n), 2, 'limiar') : sX(Math.round(8 * n));
