  const comLongao = niv !== 'ini' && !rec && !pol && f >= 0.9 && !provas.some((p) => p.papel === 'forte') && !S.some(([, t]) => t.tipo === 'longao');
  provas.forEach((p) => S.push([p.d, sPr(p.km, p.papel, p.rot, comLongao && p.d === 6 ? L * 0.85 - p.km - (p.papel === 'treino' ? 3 : 0) : 0)]));
