    if (x.fase !== (W[i - 1] || {}).fase) fase0 = i;
    const prog = i / n, f = (x.rec ? 0.75 : 1) * lerp(0.85, 1.12, x.fase === 'Competitiva' ? 0.8 : prog * 1.4) * (x.fase === 'Base' && i - fase0 < 2 ? 0.92 : 1);
